import numpy as np

grid = np.array([
    [2, 2, 4, 9, 2],
    [9, 9, 4, 9, 2],
    [4, 4, 4, 4, 4],
    [9, 2, 4, 2, 2],
    [2, 2, 4, 2, 9],
    [4, 4, 4, 4, 4],
    [2, 9, 4, 2, 2],
    [9, 2, 4, 9, 2]
])

# Apply consistent tie-breaking (sort keys, pick first max count, then first in sorted list)
output_3x2_tiebreak = []
for ri in range(3):
    if ri == 0:
        r_start, r_end = 0, 1
    elif ri == 1:
        r_start, r_end = 3, 4
    else:
        r_start, r_end = 6, 7

    for ci in range(2):
        if ci == 0:
            c_start, c_end = 0, 1
        else:
            c_start, c_end = 3, 4

        cell = grid[r_start:r_end+1, c_start:c_end+1]

        counts = {}
        for r in range(2):
            for c in range(2):
                v = cell[r, c]
                if v != 4:
                    counts[v] = counts.get(v, 0) + 1

        print(f"Cell ({ri},{ci}): {cell.flatten()}, counts={dict(counts)}")

        if counts:
            # Sort by (-count, value) to get highest count first, then smallest value for ties
            result = min(counts.items(), key=lambda x: (-x[1], x[0]))[0]
        else:
            result = 0
        output_3x2_tiebreak.append(result)

out = np.array(output_3x2_tiebreak).reshape(3, 2)
print(f"\n3x2 output (sorted tiebreak):")
print(out.tolist())

